'use strict';

function _setup(context) {

	var $ = context.jQuery;

	//New custom validation
	$.validator.addMethod('min-date', function (value, element) {

		var $element = $(element);
		var validation = $element.data('rule-min-date').toString();
		var date = $element.parent('.date').data('DateTimePicker').getDate()._d;
		var today = new Date();
		var days;

		//If the date is today. Ex: today
		if (validation === 'today') {

			today = new Date(today.setHours(0, 0, 0, 0));

			return date.getTime() === today.getTime();

		}

		//Validate today-tomorrow / next days
		if (validation.indexOf('+') > -1) {

			//If the date is today-tomorrow. Ex: +today
			if (validation === '+today') {

				today = new Date(today.setHours(0, 0, 0, 0));

				return date.getTime() >= today.getTime();

			//If there are days. Ex: +1
			} else {

				days = validation.split('+');

				var tomorrow = new Date(today.setHours(0, 0, 0, 0) + (days[1] * 24 * 60 * 60 * 1000));

				return date.getTime() >= tomorrow.getTime();

			}

		}

		//Validate today-yesterday / prev days
		if (validation.indexOf('-') > -1) {

			//If the date is today-yesterday. Ex: -today
			if (validation === '-today') {

				today = new Date(today.setHours(0, 0, 0, 0));

				return date.getTime() <= today.getTime();

			//If there are days. Ex: -1
			} else {

				days = validation.split('-');

				var yesterday = new Date(today.setHours(0, 0, 0, 0) - (days[1] * 24 * 60 * 60 * 1000));

				return date.getTime() <= yesterday.getTime();

			}

		}
		

	});

}

module.exports = {
	setup: _setup
};
